@Suite("SkylineResizeFlow")
final class SkylineResizeFlow {
    private static let resizeTex: String = "\n        \\track \"Guitar\"\n        :4 17.1 19.1 22.1 24.1 |\n        12.1{v f} 14.1{v f}.4 :8 15.1 17.1 |\n        :4 0.6 0.6 0.6 0.6 |\n        :4 12.1 14.1 17.1 0.6 |\n        :4 22.1 24.1 17.1 19.1 |\n        :4 12.1 12.6 17.1 0.6\n    "

    @Test("initial render at a wide width populates the staff skyline")
    func initialRenderAtAWideWidthPopulatesTheStaffSkyline() async throws {
        let snap: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 1300.0)
        TestGlobals.expect(snap.length).toBeGreaterThan(0.0)
        TestGlobals.expect(SkylineResizeFlowHelper.anyStaffHasContent(snap)).toBe(true)
        for staff in snap {
            do {
                var i: Double = 0.0
                while i < staff.barUpMaxes.length {
                    TestGlobals.expect(staff.barUpMaxes[(i).toInt()] + staff.barDownMaxes[(i).toInt()]).toBeGreaterThan(0.0)
                    i += 1
                }
            }
        }
    }

    @Test("initial render at a narrow width populates skylines across multiple systems")
    func initialRenderAtANarrowWidthPopulatesSkylinesAcrossMultipleSystems() async throws {
        let snap: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 600.0)
        TestGlobals.expect(snap.length).toBeGreaterThan(0.0)
        TestGlobals.expect(SkylineResizeFlowHelper.distinctSystemCount(snap)).toBeGreaterThanOrEqual(2.0)
        for staff in snap {
            if SkylineResizeFlowHelper.anyBarHasContent(staff) {
                TestGlobals.expect(staff.upMax + staff.downMax).toBeGreaterThan(0.0)
            }
        }
    }

    @Test("same bar count is produced regardless of width (fresh API per render)")
    func sameBarCountIsProducedRegardlessOfWidth_freshAPIPerRender_() async throws {
        let wide: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 1300.0)
        let narrow: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 600.0)
        TestGlobals.expect(SkylineResizeFlowHelper.totalBarsInSnapshot(wide)).toBe(SkylineResizeFlowHelper.totalBarsInSnapshot(narrow))
    }

    @Test("per-staff envelope totals are stable across widths (fresh APIs)")
    func perStaffEnvelopeTotalsAreStableAcrossWidths_freshAPIs_() async throws {
        let wide: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 1300.0)
        let narrow: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 600.0)
        let a: Map<String, UpDownArrays> = try SkylineResizeFlowHelper.envelopesByStaff(wide)
        let b: Map<String, UpDownArrays> = try SkylineResizeFlowHelper.envelopesByStaff(narrow)
        TestGlobals.expect(a.size).toBe(b.size)
        for (staffKey, ea) in a {
            let eb: UpDownArrays = try jsNonNull(b.get(staffKey))
            TestGlobals.expect(SkylineResizeFlowHelper.maxOrZero(ea.up)).toBeCloseTo(SkylineResizeFlowHelper.maxOrZero(eb.up), 3.0)
            TestGlobals.expect(SkylineResizeFlowHelper.maxOrZero(ea.down)).toBeCloseTo(SkylineResizeFlowHelper.maxOrZero(eb.down), 3.0)
        }
    }

    @Test("single resize wide→narrow re-distributes bars across systems")
    func singleResizeWide_narrowReDistributesBarsAcrossSystems() async throws {
        let snapshots: SkylineResizeSnapshots = try await SkylineResizeFlowHelper.renderWithResize((SkylineResizeFlow.resizeTex), 1300.0, 600.0)
        let initial: List<StaffSkylineResizeSnapshot> = snapshots.initial
        let resized: List<StaffSkylineResizeSnapshot> = snapshots.resized
        TestGlobals.expect(initial.length).toBeGreaterThan(0.0)
        TestGlobals.expect(resized.length).toBeGreaterThan(0.0)
        let initialSystems: Double = SkylineResizeFlowHelper.distinctSystemCount(initial)
        let resizedSystems: Double = SkylineResizeFlowHelper.distinctSystemCount(resized)
        TestGlobals.expect(resizedSystems).toBeGreaterThanOrEqual(initialSystems)
        for staff in resized {
            if SkylineResizeFlowHelper.anyBarHasContent(staff) {
                TestGlobals.expect(staff.upMax + staff.downMax).toBeGreaterThan(0.0)
            }
        }
    }

    @Test("single resize narrow→wide preserves bar-local envelopes")
    func singleResizeNarrow_widePreservesBarLocalEnvelopes() async throws {
        let snapshots: SkylineResizeSnapshots = try await SkylineResizeFlowHelper.renderWithResize((SkylineResizeFlow.resizeTex), 600.0, 900.0)
        let initial: Map<String, Double> = SkylineResizeFlowHelper.barMagnitudes(snapshots.initial)
        let resized: Map<String, Double> = SkylineResizeFlowHelper.barMagnitudes(snapshots.resized)
        var compared: Double = 0.0
        for (key, value) in initial {
            if resized.has(key) {
                try TestGlobals.expect(jsNonNull(resized.get(key)), key).toBeCloseTo(value, 5.0)
                compared += 1
            }
        }
        TestGlobals.expect(compared).toBeGreaterThan(0.0)
    }

    @Test("bars in each staff are contiguous (no gaps or overlaps) after resize")
    func barsInEachStaffAreContiguous_noGapsOrOverlaps_AfterResize() async throws {
        let snapshots: SkylineResizeSnapshots = try await SkylineResizeFlowHelper.renderWithResize((SkylineResizeFlow.resizeTex), 1300.0, 800.0)
        let resized: List<StaffSkylineResizeSnapshot> = snapshots.resized
        let tolerance: Double = 1.5
        for staff in resized {
            if staff.barLineLocalX.length == 0.0 {
                continue
            }
            var expectedX: Double = staff.barLineLocalX[0]
            do {
                var i: Double = 0.0
                while i < staff.barLineLocalX.length {
                    TestGlobals.expect(Math.abs(staff.barLineLocalX[(i).toInt()] - expectedX)).toBeLessThanOrEqual(tolerance)
                    expectedX += staff.barWidths[(i).toInt()]
                    i += 1
                }
            }
        }
    }

    @Test("staff skyline maxHeight is at least the max over its constituent bar-local maxHeights")
    func staffSkylineMaxHeightIsAtLeastTheMaxOverItsConstituentBarLocalMaxHeights() async throws {
        let snap: List<StaffSkylineResizeSnapshot> = try await SkylineResizeFlowHelper.renderOnce((SkylineResizeFlow.resizeTex), 600.0)
        for staff in snap {
            let localUpMax: Double = SkylineResizeFlowHelper.maxOrZero(staff.barUpMaxes)
            let localDownMax: Double = SkylineResizeFlowHelper.maxOrZero(staff.barDownMaxes)
            TestGlobals.expect(staff.upMax).toBeGreaterThanOrEqual(localUpMax - 0.00001)
            TestGlobals.expect(staff.downMax).toBeGreaterThanOrEqual(localDownMax - 0.00001)
        }
    }

